# -*- coding: utf-8 -*-
"""
motor_linkedin.py
--------------------------------------------------------------------
Genera el BOLETÍN DE CONTRATACIÓN en formato IMAGEN (PNG) para LinkedIn:
  - 1 portada (fondo con foto, título, edición, objetivo, llamado a la acción, logo)
  - N páginas de contenido (4 proyectos por página, sin enlaces)

Todo lo editable (objetivo, edición, textos, colores, fondo) vive en un
diccionario CONFIG, para que la futura app web pueda guardarlo y reutilizarlo.

Para resaltar palabras en el OBJETIVO o en el texto del botón, enciérralas
entre asteriscos:  *Fomentar oportunidades*  -> saldrá en negrilla y color de acento.
--------------------------------------------------------------------
"""

import os, io, re, json, base64, zipfile, datetime, urllib.request
import pandas as pd
from PIL import Image, ImageDraw, ImageFont, ImageFilter

# =====================================================================
# 1. CONFIGURACIÓN POR DEFECTO (lo que la app podrá editar y guardar)
# =====================================================================
CONFIG_DEFAULT = {
    "edicion": "EDICIÓN NO. 10 - 2026",
    "objetivo": ("*Fomentar oportunidades* para las empresas del sector a través de la "
                 "provisión continua de información sobre *proyectos* y *convocatorias* de "
                 "licitación pública de obra civil, interventoría y consultoría de estudios "
                 "y diseños que están próximos a desarrollarse."),
    "texto_boton": ("DESLIZA Y CONOCE *NUEVAS*|*OPORTUNIDADES* PARA TU EMPRESA EN EL|"
                    "*SECTOR DE LA INFRAESTRUCTURA*"),
    "fuente_datos": "SECOP I y II",
    "fecha_actualizacion": "",          # vacío = fecha de hoy
    "proyectos_por_pagina": 4,
    # ---- colores (hex) ----
    "color_fondo_portada":   "#0B3A6E",
    "color_texto_portada":   "#FFFFFF",
    "color_acento":          "#F7941D",
    "color_texto_objetivo":  "#FFFFFF",
    "color_fondo_contenido": "#F6F6F6",
    "color_titulo_1":        "#111111",
    "color_titulo_2":        "#0056A5",
    "color_barra_proyecto":  "#0B3E70",
    "color_texto_barra":     "#FFFFFF",
    "color_etiquetas":       "#0B3E70",
    "color_valores":         "#3A3A3A",
    "color_pie":             "#034E7B",
}

W, H = 1080, 1376      # proporción del diseño original (≈ 4:5, ideal para LinkedIn)
SS = 2                 # supermuestreo para bordes suaves


def s(v):
    return int(round(v * SS))


def hex2rgb(h, a=None):
    h = h.lstrip("#")
    rgb = tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))
    return rgb + (a,) if a is not None else rgb


# =====================================================================
# 2. RECURSOS: fuentes, logos y fondo por defecto
# =====================================================================
BASE_DIR = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
FONT_DIR = os.path.join(BASE_DIR, "fonts")
POPPINS = {
    "regular": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Regular.ttf",
    "medium": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Medium.ttf",
    "bold": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Bold.ttf",
    "semibold": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-SemiBold.ttf",
}
FALLBACKS = {
    "regular": ["Roboto-Regular.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
                "/usr/share/fonts/liberation/LiberationSans-Regular.ttf", "DejaVuSans.ttf"],
    "medium": ["Roboto-Regular.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
               "/usr/share/fonts/liberation/LiberationSans-Regular.ttf", "DejaVuSans.ttf"],
    "bold": ["Roboto-Bold.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
             "/usr/share/fonts/liberation/LiberationSans-Bold.ttf", "DejaVuSans-Bold.ttf"],
    "semibold": ["Roboto-Bold.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
                 "/usr/share/fonts/liberation/LiberationSans-Bold.ttf", "DejaVuSans-Bold.ttf"],
}
_FONT_PATHS = {}


def preparar_fuentes():
    """Descarga Poppins (la tipografía del diseño). Si no hay internet, usa una alternativa."""
    os.makedirs(FONT_DIR, exist_ok=True)
    for peso, url in POPPINS.items():
        destino = os.path.join(FONT_DIR, os.path.basename(url))
        if not os.path.exists(destino):
            try:
                urllib.request.urlretrieve(url, destino)
            except Exception:
                pass
        ok = False
        if os.path.exists(destino):
            try:
                ImageFont.truetype(destino, 10)
                _FONT_PATHS[peso] = destino
                ok = True
            except Exception:
                pass
        if not ok:
            for fb in FALLBACKS[peso]:
                cand = fb if os.path.isabs(fb) else os.path.join(FONT_DIR, fb)
                for c in (cand, fb):
                    try:
                        ImageFont.truetype(c, 10)
                        _FONT_PATHS[peso] = c
                        ok = True
                        break
                    except Exception:
                        continue
                if ok:
                    break
        if not ok:
            _FONT_PATHS[peso] = None


_font_cache = {}


def F(peso, size):
    if not _FONT_PATHS:
        preparar_fuentes()
    key = (peso, size)
    if key not in _font_cache:
        p = _FONT_PATHS.get(peso)
        _font_cache[key] = ImageFont.truetype(p, s(size)) if p else ImageFont.load_default()
    return _font_cache[key]


LOGO_COLOR_B64 = ""
LOGO_BLANCO_B64 = ""
FONDO_DEFAULT_B64 = ""


def _img_b64(b64):
    return Image.open(io.BytesIO(base64.b64decode(b64)))


# =====================================================================
# 3. DATOS
# =====================================================================
COLUMNAS = ["NOMBRE DEL PROYECTO", "No PROCESO", "CATEGORÍA DE PROYECTO", "DEPARTAMENTO",
            "MUNICIPIO INICIAL", "VALOR MILLONES COP", "ENTIDAD CONTRATANTE"]


def normalizar_link(url):
    url = (url or "").strip()
    m = re.search(r"/spreadsheets/d/([a-zA-Z0-9-_]+)", url)
    if not m:
        return url
    g = re.search(r"[?&#]gid=(\d+)", url)
    return f"https://docs.google.com/spreadsheets/d/{m.group(1)}/export?format=csv&gid={g.group(1) if g else '0'}"


def cargar_datos(url_o_ruta):
    df = pd.read_csv(normalizar_link(url_o_ruta), dtype=str)
    df.columns = [str(c).strip() for c in df.columns]
    faltan = [c for c in COLUMNAS if c not in df.columns]
    if faltan:
        raise ValueError("Faltan columnas en la hoja: " + ", ".join(faltan) +
                         "\nColumnas encontradas: " + ", ".join(df.columns))
    df = df.fillna("")
    df = df[df["NOMBRE DEL PROYECTO"].str.strip() != ""]
    return df.reset_index(drop=True)


def formatear_valor(v):
    t = str(v).strip().replace("$", "").replace(" ", "")
    if not t:
        return ""
    try:
        if "," in t and "." in t:
            num = float(t.replace(".", "").replace(",", ".")) if t.rfind(",") > t.rfind(".") \
                else float(t.replace(",", ""))
        elif "," in t:
            partes = t.split(",")
            num = float(t.replace(",", ".")) if len(partes) == 2 and len(partes[1]) != 3 \
                else float(t.replace(",", ""))
        elif t.count(".") > 1 or (t.count(".") == 1 and len(t.split(".")[1]) == 3):
            num = float(t.replace(".", ""))
        else:
            num = float(t)
    except ValueError:
        return str(v)
    return f"{num:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


# =====================================================================
# 4. UTILIDADES DE TEXTO
# =====================================================================
def tokens_resaltados(texto):
    """'hola *mundo bonito*' -> [('hola',False),('mundo',True),('bonito',True)]"""
    out = []
    texto = texto.replace("|", " \x00 ")
    for i, parte in enumerate(re.split(r"\*", texto)):
        for w in parte.split():
            out.append((w, i % 2 == 1))
    return out


def envolver_tokens(tokens, f_reg, f_bold, ancho):
    lineas, actual, w_act = [], [], 0
    esp = f_reg.getlength(" ")
    for w, b in tokens:
        if w == "\x00":
            if actual:
                lineas.append(actual + [("\x00", b, 0)])
            actual, w_act = [], 0
            continue
        lw = (f_bold if b else f_reg).getlength(w)
        extra = lw + (esp if actual else 0)
        if actual and w_act + extra > ancho:
            lineas.append(actual)
            actual, w_act = [(w, b, lw)], lw
        else:
            actual.append((w, b, lw))
            w_act += extra
    if actual:
        lineas.append(actual)
    return lineas


def envolver(texto, font, ancho):
    palabras, lineas, act = str(texto).split(), [], ""
    for p in palabras:
        prueba = (act + " " + p).strip()
        if font.getlength(prueba) <= ancho or not act:
            act = prueba
        else:
            lineas.append(act)
            act = p
    if act:
        lineas.append(act)
    return lineas or [""]


# =====================================================================
# 5. PORTADA
# =====================================================================
def _cover_fit(img, w, h):
    img = img.convert("RGB")
    r = max(w / img.width, h / img.height)
    img = img.resize((int(img.width * r) + 1, int(img.height * r) + 1), Image.LANCZOS)
    x, y = (img.width - w) // 2, 0 if img.height - h < 4 else int((img.height - h) * 0.35)
    return img.crop((x, y, x + w, y + h))


def generar_portada(cfg, fondo=None):
    c = {**CONFIG_DEFAULT, **(cfg or {})}
    navy = hex2rgb(c["color_fondo_portada"])
    acento = hex2rgb(c["color_acento"])
    blanco = hex2rgb(c["color_texto_portada"])

    img = Image.new("RGBA", (s(W), s(H)), navy + (255,))
    foto = fondo if fondo is not None else _img_b64(FONDO_DEFAULT_B64)
    alto_foto = 780
    foto = _cover_fit(foto, s(W), s(alto_foto)).convert("RGBA")
    img.alpha_composite(foto, (0, 0))

    # Degradado de la foto hacia el azul
    grad = Image.new("RGBA", (s(W), s(alto_foto)), navy + (0,))
    gd = ImageDraw.Draw(grad)
    ini, fin = 300, alto_foto
    for y in range(s(ini), s(fin)):
        t = (y - s(ini)) / (s(fin) - s(ini))
        a = int(255 * min(1, t ** 0.9))
        gd.line([(0, y), (s(W), y)], fill=navy + (a,))
    img.alpha_composite(grad, (0, 0))
    d = ImageDraw.Draw(img)

    # Título
    d.text((s(92), s(488)), "BOLETÍN DE", font=F("regular", 50), fill=blanco)
    f_tit = F("bold", 84)
    while f_tit.getlength("CONTRATACIÓN") > s(700):
        f_tit = ImageFont.truetype(f_tit.path, f_tit.size - 2)
    d.text((s(88), s(538)), "CONTRATACIÓN", font=f_tit, fill=blanco)
    d.text((s(98), s(648)), c["edicion"], font=F("bold", 20), fill=blanco)

    # ---- Texto del objetivo: se calcula primero para que la caja se adapte ----
    bx0, bx1, by0 = 94, 1006, 712
    color_txt = hex2rgb(c["color_texto_objetivo"])
    ancho = s(bx1 - bx0 - 80)
    toks = tokens_resaltados(c["objetivo"])
    tam = 28
    while True:
        fr, fb = F("regular", tam), F("bold", tam)
        lineas = envolver_tokens(toks, fr, fb, ancho)
        lh = s(tam * 1.5)
        alto_txt = len(lineas) * lh
        if alto_txt <= s(260) or tam <= 14:
            break
        tam -= 1
    by1 = by0 + (alto_txt / SS) + 84

    capa = Image.new("RGBA", img.size, (0, 0, 0, 0))
    ImageDraw.Draw(capa).rounded_rectangle([s(bx0), s(by0), s(bx1), s(by1)], radius=s(14),
                                           fill=(0, 0, 0, 40))
    img.alpha_composite(capa)
    d = ImageDraw.Draw(img)
    d.rounded_rectangle([s(bx0), s(by0), s(bx1), s(by1)], radius=s(14), outline=blanco, width=s(2.5))

    # Píldora OBJETIVO
    pw, ph = 250, 54
    px0, py0 = W / 2 - pw / 2, by0 - ph / 2
    d.rounded_rectangle([s(px0), s(py0), s(px0 + pw), s(py0 + ph)], radius=s(ph / 2), fill=acento)
    d.text((s(W / 2), s(by0)), "OBJETIVO", font=F("bold", 27), fill=(255, 255, 255), anchor="mm")

    y = s(by0 + 46)
    for i, linea in enumerate(lineas):
        forzado = linea and linea[-1][0] == "\x00"
        linea = [t for t in linea if t[0] != "\x00"]
        x = s(bx0 + 40)
        total = sum(t[2] for t in linea)
        huecos = len(linea) - 1
        esp = fr.getlength(" ")
        if i < len(lineas) - 1 and huecos > 0 and not forzado:
            esp = (ancho - total) / huecos
        for w, b, lw in linea:
            d.text((x, y), w, font=fb if b else fr, fill=acento if b else color_txt)
            x += lw + esp
        y += lh

    # ---- Botón "Desliza..." (debajo de la caja) ----
    cy0 = by1 + 28
    cx0, cx1, cy1 = 90, 1010, by1 + 28 + 128
    d.rounded_rectangle([s(cx0), s(cy0), s(cx1), s(cy1)], radius=s((cy1 - cy0) / 2),
                        fill=(255, 255, 255), outline=acento, width=s(4))
    r = 50
    ccx, ccy = cx1 - 22 - r, (cy0 + cy1) / 2
    d.ellipse([s(ccx - r), s(ccy - r), s(ccx + r), s(ccy + r)], fill=acento)
    d.line([(s(ccx - 12), s(ccy - 24)), (s(ccx + 14), s(ccy)), (s(ccx - 12), s(ccy + 24))],
           fill=(255, 255, 255), width=s(12), joint="curve")
    for (px, py) in [(ccx - 12, ccy - 24), (ccx + 14, ccy), (ccx - 12, ccy + 24)]:
        d.ellipse([s(px - 6), s(py - 6), s(px + 6), s(py + 6)], fill=(255, 255, 255))
    area_x0, area_x1 = cx0 + 40, ccx - r - 20
    toks = tokens_resaltados(c["texto_boton"])
    tam = 31
    while True:
        fr, fb = F("regular", tam), F("bold", tam)
        lineas = envolver_tokens(toks, fr, fb, s(area_x1 - area_x0))
        lh = s(tam * 1.18)
        if len(lineas) * lh <= s(cy1 - cy0 - 26) or tam <= 14:
            break
        tam -= 1
    y = s(ccy) - len(lineas) * lh / 2
    for linea in lineas:
        linea = [t for t in linea if t[0] != "\x00"]
        esp = fr.getlength(" ")
        tot = sum(t[2] for t in linea) + esp * (len(linea) - 1)
        x = s((area_x0 + area_x1) / 2) - tot / 2
        for w, b, lw in linea:
            d.text((x, y), w, font=fb if b else fr, fill=acento)
            x += lw + esp
        y += lh

    # Logo blanco
    logo = _img_b64(LOGO_BLANCO_B64).convert("RGBA")
    lw_ = s(480)
    logo = logo.resize((lw_, int(logo.height * lw_ / logo.width)), Image.LANCZOS)
    y_logo = max(s(cy1 + 24), s(H - 40) - logo.height)
    img.alpha_composite(logo, ((s(W) - lw_) // 2, int(y_logo)))

    return img.resize((W, H), Image.LANCZOS).convert("RGB")


