# 6. PÁGINAS DE CONTENIDO
# =====================================================================
def _fondo_contenido(c):
    base = hex2rgb(c["color_fondo_contenido"])
    img = Image.new("RGBA", (s(W), s(H)), base + (255,))
    capa = Image.new("RGBA", img.size, (0, 0, 0, 0))
    dc = ImageDraw.Draw(capa)
    for pts, a in [([(620, 0), (1080, 0), (1080, 380)], 150),
                   ([(780, 0), (1080, 0), (1080, 220)], 120),
                   ([(1080, 900), (1080, 1376), (560, 1376)], 140),
                   ([(1080, 1150), (1080, 1376), (850, 1376)], 110),
                   ([(0, 1100), (0, 1376), (300, 1376)], 90)]:
        dc.polygon([(s(x), s(y)) for x, y in pts], fill=(255, 255, 255, a))
    img.alpha_composite(capa)
    return img


def _encabezado(img, c):
    d = ImageDraw.Draw(img)
    d.rectangle([s(54), s(30), s(61), s(138)], fill=hex2rgb(c["color_acento"]))
    d.text((s(84), s(28)), "BOLETÍN DE", font=F("regular", 42), fill=hex2rgb(c["color_titulo_1"]))
    d.text((s(82), s(76)), "CONTRATACIÓN", font=F("bold", 56), fill=hex2rgb(c["color_titulo_2"]))
    # Píldora blanca con logo a color
    sombra = Image.new("RGBA", img.size, (0, 0, 0, 0))
    ImageDraw.Draw(sombra).rounded_rectangle([s(668), s(28), s(W + 80), s(156)], radius=s(64),
                                             fill=(0, 0, 0, 35))
    sombra = sombra.filter(ImageFilter.GaussianBlur(s(8)))
    img.alpha_composite(sombra)
    d = ImageDraw.Draw(img)
    d.rounded_rectangle([s(664), s(22), s(W + 80), s(150)], radius=s(64), fill=(255, 255, 255))
    logo = _img_b64(LOGO_COLOR_B64).convert("RGBA")
    lw_ = s(350)
    logo = logo.resize((lw_, int(logo.height * lw_ / logo.width)), Image.LANCZOS)
    img.alpha_composite(logo, (s(706), s(86) - logo.height // 2))


def _pie(img, c, fecha):
    d = ImageDraw.Draw(img)
    x0, y0, x1, y1 = 64, 1278, 1018, 1340
    d.rounded_rectangle([s(x0), s(y0), s(x1), s(y1)], radius=s(31), fill=hex2rgb(c["color_pie"]))
    pie = hex2rgb(c["color_pie"])
    cy = (y0 + y1) / 2
    f = F("bold", 24)
    # Lupa
    ix = 120
    d.ellipse([s(ix - 21), s(cy - 21), s(ix + 21), s(cy + 21)], fill=(255, 255, 255))
    d.ellipse([s(ix - 11), s(cy - 12), s(ix + 7), s(cy + 6)], outline=pie, width=s(4))
    d.line([(s(ix + 5), s(cy + 4)), (s(ix + 13), s(cy + 12))], fill=pie, width=s(5))
    d.text((s(ix + 34), s(cy)), f"Fuente: {c['fuente_datos']}", font=f, fill=(255, 255, 255), anchor="lm")
    # Engranaje
    import math
    gx = 498
    d.ellipse([s(gx - 21), s(cy - 21), s(gx + 21), s(cy + 21)], fill=(255, 255, 255))
    pts = []
    for i in range(16):
        ang = math.pi * i / 8
        r = 14 if i % 2 == 0 else 10.5
        pts.append((s(gx + r * math.cos(ang)), s(cy + r * math.sin(ang))))
    d.polygon(pts, fill=pie)
    d.ellipse([s(gx - 5), s(cy - 5), s(gx + 5), s(cy + 5)], fill=(255, 255, 255))
    d.text((s(gx + 34), s(cy)), f"Fecha de Actualización: {fecha}", font=f, fill=(255, 255, 255),
           anchor="lm")


def _medir_tarjeta(fila, esc):
    fb_bar = F("bold", round(21 * esc))
    nombre = envolver(str(fila["NOMBRE DEL PROYECTO"]).upper(), fb_bar, s(1042 - 47 - 70))
    lh_bar = s(21 * esc * 1.32)
    alto_barra = len(nombre) * lh_bar + s(2 * 22 * esc)

    fl, fv = F("bold", round(18.5 * esc)), F("regular", round(18.5 * esc))
    lh = s(18.5 * esc * 1.45)
    izq = [("NO. PROCESO:", fila["No PROCESO"]),
           ("DEPARTAMENTO:", fila["DEPARTAMENTO"]),
           ("VALOR MILLONES COP:", formatear_valor(fila["VALOR MILLONES COP"]))]
    der = [("CATEGORÍA DE PROYECTO:", fila["CATEGORÍA DE PROYECTO"]),
           ("MUNICIPIO INICIAL:", fila["MUNICIPIO INICIAL"]),
           ("ENTIDAD CONTRATANTE:", fila["ENTIDAD CONTRATANTE"])]
    cols = [(118, 470), (602, 410)]   # (x inicio texto, ancho disponible)
    filas_layout = []
    for (li, vi), (ld, vd) in zip(izq, der):
        celdas = []
        for (lab, val), (cx, cw) in zip([(li, vi), (ld, vd)], cols):
            lab_w = fl.getlength(lab + " ")
            lineas = envolver(str(val).strip(), fv, s(cw) - lab_w)
            celdas.append((lab, lab_w, lineas, cx))
        n = max(len(cel[2]) for cel in celdas)
        filas_layout.append((celdas, n))
    gap_fila = s(14 * esc)
    alto_cuerpo = sum(n * lh for _, n in filas_layout) + gap_fila * (len(filas_layout) - 1) + s(2 * 24 * esc)
    return dict(nombre=nombre, lh_bar=lh_bar, alto_barra=alto_barra, fb_bar=fb_bar, fl=fl, fv=fv,
                lh=lh, filas=filas_layout, gap_fila=gap_fila, alto_cuerpo=alto_cuerpo, esc=esc)


def _dibujar_tarjeta(img, c, m, y):
    esc = m["esc"]
    y = int(y)
    bx0, bx1 = s(47), s(1042)
    cx0, cx1 = s(76), s(1030)
    yb1 = int(y + m["alto_barra"])
    yc1 = int(yb1 + m["alto_cuerpo"])
    # sombra
    sh = Image.new("RGBA", img.size, (0, 0, 0, 0))
    ImageDraw.Draw(sh).rectangle([cx0 + s(4), yb1, cx1 + s(4), yc1 + s(6)], fill=(0, 0, 0, 28))
    sh = sh.filter(ImageFilter.GaussianBlur(s(7)))
    img.alpha_composite(sh)
    d = ImageDraw.Draw(img)
    d.rectangle([cx0, yb1 - s(5), cx1, yc1], fill=(255, 255, 255))
    rad = int(min(s(40), m["alto_barra"] // 2 - 4))
    d.rounded_rectangle([bx0, y, bx1, yb1], radius=rad, fill=hex2rgb(c["color_barra_proyecto"]),
                        corners=(False, True, True, False))
    ty = y + s(22 * esc)
    for ln in m["nombre"]:
        d.text((s(80), ty), ln, font=m["fb_bar"], fill=hex2rgb(c["color_texto_barra"]))
        ty += m["lh_bar"]
    col_lab, col_val = hex2rgb(c["color_etiquetas"]), hex2rgb(c["color_valores"])
    ty = yb1 + s(24 * esc)
    for celdas, n in m["filas"]:
        for lab, lab_w, lineas, cx in celdas:
            by = ty + m["lh"] / 2
            r = s(3.6 * esc)
            d.ellipse([s(cx - 22) - r, by - r, s(cx - 22) + r, by + r], fill=col_lab)
            d.text((s(cx), ty), lab, font=m["fl"], fill=col_lab)
            vy = ty
            for ln in lineas:
                d.text((s(cx) + lab_w, vy), ln, font=m["fv"], fill=col_val)
                vy += m["lh"]
        ty += n * m["lh"] + m["gap_fila"]
    return yc1


def generar_pagina(filas, cfg, fecha):
    c = {**CONFIG_DEFAULT, **(cfg or {})}
    img = _fondo_contenido(c)
    _encabezado(img, c)
    top, bottom = s(178), s(1256)
    esc = 1.0
    while True:
        medidas = [_medir_tarjeta(f, esc) for f in filas]
        total = sum(m["alto_barra"] + m["alto_cuerpo"] for m in medidas)
        gap_min = s(22)
        if total + gap_min * max(len(filas) - 1, 0) <= bottom - top or esc <= 0.6:
            break
        esc -= 0.04
    libre = (bottom - top) - total
    gap = min(s(46), libre / max(len(filas), 1)) if filas else 0
    y = top
    for m in medidas:
        y = _dibujar_tarjeta(img, c, m, y) + gap
    _pie(img, c, fecha)
    return img.resize((W, H), Image.LANCZOS).convert("RGB")


