# 7. FUNCIÓN PRINCIPAL
# =====================================================================
def generar_boletin(df, cfg=None, fondo=None):
    """Devuelve una lista de imágenes PIL: [portada, página 1, página 2, ...]"""
    c = {**CONFIG_DEFAULT, **(cfg or {})}
    fecha = c["fecha_actualizacion"] or datetime.date.today().strftime("%d/%m/%Y")
    n = int(c["proyectos_por_pagina"])
    filas = df.to_dict("records")
    paginas = [generar_portada(c, fondo)]
    for i in range(0, len(filas), n):
        paginas.append(generar_pagina(filas[i:i + n], c, fecha))
    return paginas


def exportar_zip(paginas):
    """ZIP con cada página en PNG + un PDF (carrusel de LinkedIn)."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for i, p in enumerate(paginas):
            nombre = "00_portada.png" if i == 0 else f"{i:02d}_pagina_{i}.png"
            b = io.BytesIO(); p.save(b, "PNG"); z.writestr(nombre, b.getvalue())
        b = io.BytesIO()
        paginas[0].save(b, "PDF", save_all=True, append_images=paginas[1:], resolution=150)
        z.writestr("Boletin_carrusel_LinkedIn.pdf", b.getvalue())
    return buf.getvalue()


def cargar_config(ruta):
    if ruta and os.path.exists(ruta):
        with open(ruta, encoding="utf-8") as f:
            return {**CONFIG_DEFAULT, **json.load(f)}
    return dict(CONFIG_DEFAULT)


def guardar_config(cfg, ruta):
    with open(ruta, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=2)
